// TestPlaybackRoundTrip — packaged-playback box 4.1, the Tier-1 joint: scan →
// frontier enqueue → package → descriptor → token-gated serve, every hop a
// real instance (real serial-scanner subprocess + ffprobe, real enrich queue
// dispatch branch, real ffmpeg remux, real stream.Service serving, real api
// descriptor handler). Coverage referenced, not re-proven: the lane's lease and
// ledger semantics (enrich/streams_test.go), head-first publish internals
// (stream/pack_test.go via the afterHead hook), token issue/verify units
// (stream/media_test.go), the verb handlers (api/playback_test.go).
//
// What ONLY a joint can prove is asserted here: the lane consumes what scan
// persisted (parsed.absolute_path + ffprobe facts), the frontier fronts the
// pilot from real store state and K+1 after real watch progress, the published
// artifact is byte-servable through the /media mount with a token minted by
// the descriptor, and the stored chapters ride the verbatim ffprobe blob into
// the descriptor's sections.
package itest

import (
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func TestPlaybackRoundTrip(t *testing.T) {
	w := pbNewWorld(t)
	q := w.pbNewQueue(t, nil, 0) // plain real pack closure, production lease TTL
	enqueue := w.pbEnqueue(q)

	// --- scan: a serial library with a two-episode MKV fixture (E01 carries
	// container chapters) ---
	libRoot := filepath.Join(t.TempDir(), "lib")
	show := filepath.Join(libRoot, "Roundtrip Show")
	if err := os.MkdirAll(show, 0o755); err != nil {
		t.Fatalf("mkdir fixture: %v", err)
	}
	pbMakeMKV(t, filepath.Join(show, "Roundtrip Show E01.mkv"), 5*time.Second, true)
	pbMakeMKV(t, filepath.Join(show, "Roundtrip Show E02.mkv"), 5*time.Second, false)

	libID := pbCreateLibrary(t, w, "serial", libRoot, "QA Roundtrip")
	res := pbScanLibrary(t, w, libID)
	if res.Discovered != 3 || res.Persisted != 3 {
		t.Fatalf("scan discovered=%d persisted=%d, want 3/3 (1 serial record + 2 episodes); warnings=%v",
			res.Discovered, res.Persisted, res.Warnings)
	}
	pbAwaitIdle(t, q, 30*time.Second) // metadata chain soft-fails (plugins unloaded); drain it

	byRel := pbItemByRel(t, w, libID)
	e01, ok := byRel["Roundtrip Show/Roundtrip Show E01.mkv"]
	if !ok || e01.ID == "" {
		t.Fatalf("E01 item missing; have %v", relKeys(byRel))
	}
	e02, ok := byRel["Roundtrip Show/Roundtrip Show E02.mkv"]
	if !ok || e02.ID == "" {
		t.Fatalf("E02 item missing; have %v", relKeys(byRel))
	}

	// --- direct floor BEFORE any packaging: E02 answers mode direct at its
	// original bytes through the token-gated mount. The packable MKV floor
	// answers the honesty projection's preparing state (tv-playback-unblock
	// D1 — a pack can land; the persisted namespace still sits at none).
	if pb := pbDescriptor(t, w, e02.ID); pb.Mode != "direct" || pb.State != "preparing" {
		t.Fatalf("E02 descriptor before packaging = mode %q state %q, want direct/preparing", pb.Mode, pb.State)
	}
	origStatus, origBody, _ := pbDo(t, w.client, http.MethodGet, w.baseURL+pbDescriptor(t, w, e02.ID).PlayURL, "", nil)
	if origStatus != http.StatusOK || len(origBody) == 0 {
		t.Fatalf("direct floor: original status %d len %d, want 200 with bytes", origStatus, len(origBody))
	}
	wantBytes, _ := os.ReadFile(filepath.Join(show, "Roundtrip Show E02.mkv"))
	if string(origBody) != string(wantBytes) {
		t.Fatalf("direct floor: original bytes differ from the fixture (%d vs %d)", len(origBody), len(wantBytes))
	}

	// --- frontier fronts the pilot from real store state; the lane drains it ---
	jobs := w.pbSweep(t, enqueue)
	if len(jobs) != 1 || jobs[0].ItemID != e01.ID || jobs[0].Reason != "pilot" {
		t.Fatalf("first sweep jobs = %+v, want exactly [pilot on E01 %s]", jobs, e01.ID)
	}
	streams := pbAwaitStreams(t, w.st, e01.ID, "complete", 60*time.Second)
	pbAwaitIdle(t, q, 30*time.Second)

	// The artifact exists on disk under the persisted build-nonce directory.
	nonce, _ := streams["nonce"].(string)
	if nonce == "" {
		t.Fatalf("persisted streams missing nonce: %v", streams)
	}
	artDir := filepath.Join(w.root, e01.ID, nonce)
	entries, err := os.ReadDir(artDir)
	if err != nil {
		t.Fatalf("artifact dir %s: %v", artDir, err)
	}
	kinds := map[string]int{}
	for _, e := range entries {
		kinds[filepath.Ext(e.Name())]++
	}
	if kinds[".m3u8"] != 1 || kinds[".mp4"] == 0 || kinds[".m4s"] == 0 {
		t.Fatalf("artifact dir contents = %v, want one playlist + init.mp4 + segments", kinds)
	}

	// --- descriptor: mode hls, sections projected from the stored chapters ---
	pb := pbDescriptor(t, w, e01.ID)
	if pb.Mode != "hls" || pb.State != "complete" {
		t.Fatalf("E01 descriptor = mode %q state %q, want hls/complete", pb.Mode, pb.State)
	}
	if !strings.HasPrefix(pb.PlayURL, "/media/"+e01.ID+"/"+nonce+"/index.m3u8?token=") {
		t.Fatalf("play URL = %q, want the persisted nonce playlist with a token", pb.PlayURL)
	}
	if len(pb.Sections) != 2 {
		t.Fatalf("sections = %+v, want the fixture's 2 container chapters", pb.Sections)
	}
	// The title must ride REAL ffprobe's shape — nested under tags.title, not
	// the synthetic top-level "title" stream/media_test.go TestSections feeds
	// (that shape divergence masked a chapterTitle defect this joint caught;
	// describe.go now reads tags.title with a top-level fallback).
	if pb.Sections[0]["kind"] != "chapter" || pb.Sections[0]["title"] != "Intro" {
		t.Fatalf("sections[0] = %+v, want the Intro chapter projection (chapterTitle must read ffprobe tags.title)", pb.Sections[0])
	}

	// The descriptor mints the cookie-primary token delivery (D-6).
	descStatus, _, descHeader := pbDo(t, w.client, http.MethodGet, w.baseURL+"/api/v1/items/"+e01.ID+"/playback", w.token, nil)
	if descStatus != http.StatusOK {
		t.Fatalf("descriptor re-fetch: status %d", descStatus)
	}
	cookies := descHeader.Values("Set-Cookie")
	if len(cookies) == 0 || !strings.Contains(cookies[0], "media_token=") {
		t.Fatalf("Set-Cookie = %v, want the media_token cookie-primary delivery", cookies)
	}

	// --- token-gated serve: the playlist bytes, then a segment, then rejection ---
	plStatus, plBody, _ := pbDo(t, w.client, http.MethodGet, w.baseURL+pb.PlayURL, "", nil)
	if plStatus != http.StatusOK {
		t.Fatalf("playlist with token: status %d, want 200", plStatus)
	}
	playlist := string(plBody)
	if !strings.Contains(playlist, "#EXTM3U") || !strings.Contains(playlist, "#EXT-X-ENDLIST") {
		t.Fatalf("playlist missing EXTM3U/ENDLIST (complete build):\n%s", playlist)
	}
	if !strings.Contains(playlist, "#EXT-X-DISCONTINUITY") || !strings.Contains(playlist, "t/") {
		t.Fatalf("playlist missing the two-phase tail merge markers:\n%s", playlist)
	}
	segURI := pbFirstSegment(playlist)
	// Self-authorizing playlist (incident 2026-10-31): the served segment URI
	// itself carries the token, so a cookie-less TV client can play it.
	if !strings.Contains(segURI, "token=") {
		t.Fatalf("segment URI %q carries no token — playlists must be self-authorizing", segURI)
	}
	segStatus, segBody, segHeader := pbDo(t, w.client, http.MethodGet, w.baseURL+pbPlaylistURI(pb.PlayURL, segURI), "", nil)
	if segStatus != http.StatusOK || len(segBody) == 0 {
		t.Fatalf("segment %s: status %d len %d, want 200 with bytes", segURI, segStatus, len(segBody))
	}
	if ct := segHeader.Get("Content-Type"); ct != "video/iso.segment" {
		t.Fatalf("segment Content-Type = %q, want video/iso.segment", ct)
	}
	noTokStatus, _, _ := pbDo(t, w.client, http.MethodGet, w.baseURL+stripToken(pb.PlayURL), "", nil)
	if noTokStatus != http.StatusUnauthorized {
		t.Fatalf("playlist without token: status %d, want 401", noTokStatus)
	}

	// --- watch progress → the frontier fronts K+1; E01 is never re-packed ---
	putStatus, body, _ := pbDo(t, w.client, http.MethodPut, w.baseURL+"/api/v1/progress/"+e01.ID, w.token, map[string]any{"position_seconds": 30})
	if putStatus != http.StatusOK {
		t.Fatalf("PUT progress: status %d (body=%s)", putStatus, body)
	}
	playURLBefore := pbDescriptor(t, w, e01.ID).PlayURL
	jobs = w.pbSweep(t, enqueue)
	if len(jobs) != 1 || jobs[0].ItemID != e02.ID || jobs[0].Reason != "next-after-watched" {
		t.Fatalf("second sweep jobs = %+v, want exactly [next-after-watched on E02 %s]", jobs, e02.ID)
	}
	pbAwaitStreams(t, w.st, e02.ID, "complete", 60*time.Second)
	pbAwaitIdle(t, q, 30*time.Second)
	if pb := pbDescriptor(t, w, e02.ID); pb.Mode != "hls" || pb.State != "complete" {
		t.Fatalf("E02 descriptor after K+1 pack = mode %q state %q, want hls/complete", pb.Mode, pb.State)
	}
	// Compare the artifact POINTER (path sans query), not the full URL: the
	// play URL embeds a freshly minted token whose payload carries
	// expires.Unix() at second resolution (stream/describe.go, token.go) —
	// two mints straddling a second boundary differ in the query only, which
	// is token noise, not a repack. Same nonce/build pointer is the property.
	if got := stripToken(pbDescriptor(t, w, e01.ID).PlayURL); got != stripToken(playURLBefore) {
		t.Fatalf("E01 artifact pointer changed %q -> %q (a packaged item must never repack on a sweep)", stripToken(playURLBefore), got)
	}

	// --- saturation: nothing left past the frontier — no job, no re-pack ---
	if jobs := w.pbSweep(t, enqueue); len(jobs) != 0 {
		t.Fatalf("third sweep jobs = %+v, want none (both episodes packaged/watched)", jobs)
	}
	pbAwaitIdle(t, q, 30*time.Second)
}

// pbFirstSegment returns the first non-comment URI in an HLS playlist body.
func pbFirstSegment(playlist string) string {
	for _, l := range strings.Split(playlist, "\n") {
		l = strings.TrimSpace(l)
		if l != "" && !strings.HasPrefix(l, "#") {
			return l
		}
	}
	return ""
}

// pbPlaylistURI resolves a playlist-relative URI against the play URL's base
// path (dropping its query) so the segment request hits the same mount. A URI
// already carrying its own query (served playlists embed the token) is used
// verbatim — the cookie-less-client path.
func pbPlaylistURI(playURL, uri string) string {
	base := stripToken(playURL)
	if i := strings.LastIndex(base, "/"); i >= 0 {
		base = base[:i+1]
	}
	if strings.Contains(uri, "?") {
		return base + uri
	}
	return base + uri + "?token=" + tokenOf(playURL)
}

// stripToken removes the ?token= query (for the rejection probe).
func stripToken(playURL string) string {
	if i := strings.Index(playURL, "?"); i >= 0 {
		return playURL[:i]
	}
	return playURL
}

// tokenOf extracts the token query value from a play URL.
func tokenOf(playURL string) string {
	if i := strings.Index(playURL, "token="); i >= 0 {
		return playURL[i+len("token="):]
	}
	return ""
}

// relKeys lists a relative-path index's keys for failure messages.
func relKeys(byRel map[string]itemDTO) []string {
	out := make([]string, 0, len(byRel))
	for k := range byRel {
		out = append(out, k)
	}
	return out
}
